{% from "partials/macros.html" import pager, empty %}
{% block title %}预约服务{% endblock %}

{% block content %}
<div id="appointment-feedback" class="notice success hidden" role="status" aria-live="polite"></div>
<section class="card">
    <div class="card-header">
        <span>📅 预约单</span>
        <span class="btn-row">
            {% if can_create %}<a class="btn btn-primary btn-sm" href="/appointments/new">＋ 提交预约</a>{% endif %}
            {% if can_dispatch %}<a class="btn btn-secondary btn-sm" href="/dispatch">🧭 去派单</a>{% endif %}
        </span>
    </div>
    <form class="filter-bar" method="get" action="/appointments">
        <div class="form-field">
            <label for="status">状态</label>
            <select id="status" name="status">
                <option value="">全部状态</option>
                {% for code, name in APPOINTMENT_STATUS_NAMES.items() %}
                    <option value="{{ code }}" {% if status == code %}selected{% endif %}>{{ name }}</option>
                {% endfor %}
            </select>
        </div>
        <div class="btn-row">
            <button class="btn btn-primary" type="submit">🔍 查询</button>
            <a class="btn btn-ghost" href="/appointments">重置</a>
        </div>
    </form>

    {% if appointments %}
    <div class="table-wrap">
        <table class="data-table">
            <thead>
            <tr>
                <th>预约号</th>
                <th>老人</th>
                <th>服务项目</th>
                <th>预约时段</th>
                <th>状态</th>
                <th>创建时间</th>
                <th>说明</th>
                <th>操作</th>
            </tr>
            </thead>
            <tbody>
            {% for appt in appointments %}
            <tr>
                <td><strong>{{ appt.code }}</strong></td>
                <td>{{ (elders.get(appt.elder_id).name if elders.get(appt.elder_id) else '-')|mask_name }}</td>
                <td>{{ items.get(appt.service_item_id).name if items.get(appt.service_item_id) else '-' }}</td>
                <td class="small">
                    {{ appt.desired_start|dt }}
                    {% if appt.cycle_rule == 'weekly' %}
                        <div><span class="badge badge-blue">每周预约</span></div>
                        <div class="small muted">本次独立受理与取消</div>
                    {% endif %}
                </td>
                <td>
                    <span class="badge {{ APPOINTMENT_STATUS_BADGE.get(appt.status, 'badge-gray') }}">
                        {{ APPOINTMENT_STATUS_NAMES.get(appt.status, appt.status) }}
                    </span>
                    {% if appt.is_chargeable_cancel %}
                        <span class="badge badge-red">计费取消</span>
                    {% endif %}
                </td>
                <td class="small">{{ appt.created_at|short }}</td>
                <td class="small">
                    {% if appt.cancel_reason %}{{ '爽约' if appt.status == 'no_show' else '取消' }}原因：{{ appt.cancel_reason }}{% else %}{{ appt.remark or '-' }}{% endif %}
                    {% if appt.status == 'cancelled' %}
                        <div>取消费用：{{ '%.2f'|format(appt.cancellation_fee or 0) }} 元</div>
                        <div class="muted">本次预约已结束，不再占用时段</div>
                    {% elif appt.status == 'no_show' %}
                        <div>爽约不计费，本次预约不再占用时段</div>
                    {% endif %}
                </td>
                <td class="actions">
                    {% if can_accept and appt.status == 'pending_accept' %}
                        <button class="btn btn-success btn-sm" data-act="accept" data-id="{{ appt.id }}">受理</button>
                    {% endif %}
                    {% if can_accept and appt.status in ('accepted', 'pending_dispatch') %}
                        {% if appt.status == 'accepted' %}
                        <button class="btn btn-secondary btn-sm" data-act="to-dispatch" data-id="{{ appt.id }}">转待派单</button>
                        {% else %}
                        <a class="btn btn-secondary btn-sm" href="/dispatch">去派单</a>
                        {% endif %}
                    {% endif %}
                    {% if can_cancel and appt.status in ('pending_accept', 'accepted', 'pending_dispatch', 'dispatched') %}
                        <button class="btn btn-ghost btn-sm" data-act="cancel" data-id="{{ appt.id }}">取消</button>
                    {% endif %}
                    {% if can_accept and appt.status == 'dispatched' %}
                        <button class="btn btn-ghost btn-sm" data-act="no-show" data-id="{{ appt.id }}">登记爽约</button>
                    {% endif %}
                </td>
            </tr>
            {% endfor %}
            </tbody>
        </table>
    </div>
    {{ pager(page, pages, total, '/appointments', 'status=' ~ status) }}
    {% else %}
